import assert from 'node:assert/strict';
import { ToyRoomBattle } from '../../../../src/js/toy-room/ToyRoomBattle.js';
import { ArenaAudioProfile } from '../../../../src/js/toy-room/ArenaAudioProfile.js';
import { ARENA_SOUND_FILES } from '../../../../src/js/toy-room/ArenaSoundEffects.js';
import { arenaDifficulty } from '../../../../src/js/toy-room/ArenaDifficulty.js';
import { beginArenaSpecial, updateArenaSpecial } from '../../../../src/js/toy-room/ArenaSpecialAttack.js';
function fixture() {
 const sounds=[];
 const room={keysDown:{},gamepadState:{},touchState:{},player:{x:430,facing:'right'},clearInput(){},tutorial:{},story:{state:{},attack(){return true;}},furniture:[{id:'toy-chest'}]};
 const battle=new ToyRoomBattle(room,{loadAssets:false}),p=arenaDifficulty('NORMAL');
 const audio=new ArenaAudioProfile({playArenaSound:event=>sounds.push(event)});
 battle.presentation={enemies:p.enemies,onSound:event=>audio.sound(event)};battle.tuning=p.tuning;
 battle.activate();battle.state.transition=null;return {battle,sounds};
}
const attacks={'Steam Blast':'train_steam','Front Charge':'train_charge','Laser Beam':'robot_laser','Rocket Punch':'robot_punch',Bite:'dinosaur_bite',Rush:'dinosaur_rush','Bear Hug':'bear_hug','Belly Charge':'bear_charge','Toy Leap':'bear_leap'};
for(const [attack,event] of Object.entries(attacks)) {
 const {battle,sounds}=fixture();battle.beginEnemyAttack(attack);
 assert.equal(sounds.at(-1),event);assert.ok(ARENA_SOUND_FILES[event]);
}
for(const dt of [.5,1,3,12]) {
 const {battle,sounds}=fixture();assert.equal(beginArenaSpecial(battle),true);
 while(battle.state.specialAttack.elapsed<90)updateArenaSpecial(battle,Math.min(dt,90-battle.state.specialAttack.elapsed));
 assert.equal(sounds.filter(e=>e==='player_special').length,0);
 const restored=fixture();restored.battle.restore(battle.snapshot());
 for(const f of [{battle,sounds},restored]) {
  while(f.battle.state.specialAttack)updateArenaSpecial(f.battle,dt);
  assert.equal(f.sounds.filter(e=>e==='player_special').length,1,'Um lançamento por uso, inclusive ao carregar antes do raio');
 }
 const after=fixture();after.battle.restore(battle.snapshot());assert.equal(after.sounds.includes('player_special'),false,'Carregar após o raio não repete o efeito');
}
console.log('APROVADO: nove ataques encaminhados ao perfil de áudio e especial único no lançamento, com dt variável e restore.');
